insert into public.courses (id, category_id, title, slug, short_description, description, thumbnail_url, price_vnd, compare_at_price_vnd, level, status, badge, objectives, requirements, includes, published_at) values (md5('ks:co-5')::uuid, md5('ks:c-cloud')::uuid, 'Xây dựng High-Performance Microservices với Golang & Kubernetes', 'golang-high-performance-microservices', 'gRPC, event-driven, observability và triển khai trên Kubernetes.', 'gRPC, event-driven, observability và triển khai trên Kubernetes. Khoá học được thiết kế theo dự án thực tế: mỗi chương kết thúc bằng một bài thực hành có review, giúp bạn áp dụng ngay vào công việc.', '/images/course-golang.jpg', 1690000, 2800000, 'advanced', 'published', 'Khuyên dùng', '[{"title":"Làm chủ Golang","body":"Hiểu bản chất, không chỉ học thuộc cú pháp — áp dụng được vào dự án thật."},{"title":"Xây dựng dự án hoàn chỉnh","body":"Hoàn thành sản phẩm có thể đưa vào portfolio, kèm mã nguồn và tài liệu."},{"title":"Quy trình chuẩn doanh nghiệp","body":"Kiểm thử, review code, triển khai và giám sát như trong đội ngũ chuyên nghiệp."},{"title":"Tư duy giải quyết vấn đề","body":"Phân tích đánh đổi kỹ thuật và ra quyết định kiến trúc có cơ sở."}]'::jsonb, array['Đã làm việc thực tế ít nhất 1–2 năm','Máy tính kết nối Internet ổn định','Tinh thần tự học và thực hành đều đặn']::text[], array['Bài kiểm tra cuối chương','Truy cập trọn đời','Chứng chỉ hoàn thành có mã xác thực']::text[], '2025-06-30'::timestamptz) on conflict (slug) do nothing;
