insert into public.courses (id, category_id, title, slug, short_description, description, thumbnail_url, price_vnd, compare_at_price_vnd, level, status, badge, objectives, requirements, includes, published_at) values (md5('ks:co-10')::uuid, md5('ks:c-business')::uuid, 'Product Management Masterclass: Định hình sản phẩm số', 'product-management-masterclass', 'Từ Product Discovery, Product-Market Fit đến Growth và đo lường bằng dữ liệu.', 'Từ Product Discovery, Product-Market Fit đến Growth và đo lường bằng dữ liệu. Khoá học được thiết kế theo dự án thực tế: mỗi chương kết thúc bằng một bài thực hành có review, giúp bạn áp dụng ngay vào công việc.', '/images/course-product.jpg', 1590000, 2100000, 'beginner', 'published', null, '[{"title":"Làm chủ Product","body":"Hiểu bản chất, không chỉ học thuộc cú pháp — áp dụng được vào dự án thật."},{"title":"Xây dựng dự án hoàn chỉnh","body":"Hoàn thành sản phẩm có thể đưa vào portfolio, kèm mã nguồn và tài liệu."},{"title":"Quy trình chuẩn doanh nghiệp","body":"Kiểm thử, review code, triển khai và giám sát như trong đội ngũ chuyên nghiệp."},{"title":"Tư duy giải quyết vấn đề","body":"Phân tích đánh đổi kỹ thuật và ra quyết định kiến trúc có cơ sở."}]'::jsonb, array['Không yêu cầu kinh nghiệm trước','Máy tính kết nối Internet ổn định','Tinh thần tự học và thực hành đều đặn']::text[], array['Bài kiểm tra cuối chương','Truy cập trọn đời','Chứng chỉ hoàn thành có mã xác thực']::text[], '2025-03-14'::timestamptz) on conflict (slug) do nothing;
