insert into public.courses (id, category_id, title, slug, short_description, description, thumbnail_url, price_vnd, compare_at_price_vnd, level, status, badge, objectives, requirements, includes, published_at) values (md5('ks:co-12')::uuid, md5('ks:c-cloud')::uuid, 'Bảo mật ứng dụng web & Ethical Hacking cơ bản', 'bao-mat-ung-dung-web-ethical-hacking', 'Phòng chống lỗ hổng OWASP Top 10, kiểm thử xâm nhập và mã hoá dữ liệu.', 'Phòng chống lỗ hổng OWASP Top 10, kiểm thử xâm nhập và mã hoá dữ liệu. Khoá học được thiết kế theo dự án thực tế: mỗi chương kết thúc bằng một bài thực hành có review, giúp bạn áp dụng ngay vào công việc.', '/images/course-security.jpg', 1490000, 2050000, 'intermediate', 'published', null, '[{"title":"Làm chủ OWASP","body":"Hiểu bản chất, không chỉ học thuộc cú pháp — áp dụng được vào dự án thật."},{"title":"Xây dựng dự án hoàn chỉnh","body":"Hoàn thành sản phẩm có thể đưa vào portfolio, kèm mã nguồn và tài liệu."},{"title":"Quy trình chuẩn doanh nghiệp","body":"Kiểm thử, review code, triển khai và giám sát như trong đội ngũ chuyên nghiệp."},{"title":"Tư duy giải quyết vấn đề","body":"Phân tích đánh đổi kỹ thuật và ra quyết định kiến trúc có cơ sở."}]'::jsonb, array['Đã có kiến thức nền tảng trong lĩnh vực','Máy tính kết nối Internet ổn định','Tinh thần tự học và thực hành đều đặn']::text[], array['Bài kiểm tra cuối chương','Truy cập trọn đời','Chứng chỉ hoàn thành có mã xác thực']::text[], '2025-10-22'::timestamptz) on conflict (slug) do nothing;
